.ts-corner-br { bottom: 10px; right: 10px; border-bottom: 1px solid var(--color-accent); border-right: 1px solid var(--color-accent); }

.ts-eyebrow {
  font-family: var(--font-display);
  font-size: clamp(14px, 1.3vw, 18px);
  font-weight: 700;
  letter-spacing: var(--tracking-wider);
  margin-right: calc(-1 * var(--tracking-wider));
  text-transform: uppercase;
  color: var(--color-purple-bright);
  margin-bottom: 14px;
  text-shadow: 0 1px 8px rgba(13, 14, 31, 0.95);
}

.ts-logo {
  font-family: var(--font-display);
  font-size: clamp(40px, 7vw, 66px);
  letter-spacing: 0.08em;
  margin-right: -0.08em; /* optical centering: tracking pads the right edge */
  font-weight: 700;
  color: var(--color-text-primary);
  text-shadow: 0 2px 14px rgba(13, 14, 31, 0.95);
}
.ts-logo-accent { color: var(--color-accent); }

.ts-tag {
  margin-top: 14px;
  font-family: var(--font-display);
  font-size: clamp(16px, 1.6vw, 22px);
  letter-spacing: 0.22em;
  margin-right: -0.22em;
  text-transform: uppercase;
  color: var(--color-text-primary);
  text-shadow: 0 1px 8px rgba(13, 14, 31, 0.95);
}

.ts-brand-line {
  margin-top: 10px;
  font-family: var(--font-display);
  font-size: clamp(13px, 1.2vw, 17px);
  letter-spacing: var(--tracking-wide);
  margin-right: calc(-1 * var(--tracking-wide));
  text-transform: uppercase;
  color: var(--color-text-secondary);
  text-shadow: 0 1px 8px rgba(13, 14, 31, 0.95);
}
.ts-brand-line strong {
  font-weight: 700;
  color: var(--color-text-primary);
}

.ts-menu {
  margin-top: 44px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
}

.ts-cta-row {
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

.ts-item {
  position: relative;
  padding: 9px 30px;
  background: none;
  border: none;
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink);
  opacity: 0.85;
  cursor: pointer;
  transition: opacity 0.15s ease, color 0.15s ease, background 0.15s ease;
}
.ts-item.is-selected {
  color: var(--accent);
  opacity: 1;
  outline: none;
}
.ts-item.is-selected::before {
  content: "▸";
  position: absolute;
  left: 6px;
  top: 50%;
  transform: translateY(-50%);
}
.ts-item:focus-visible { outline: none; }

/* Primary CTA — angled purple button ("▶ START MISSION") */
.ts-item.ts-cta-primary {
  padding: 16px 44px;
  font-size: clamp(15px, 1.4vw, 19px);
  font-weight: 700;
  letter-spacing: var(--tracking-wide);
  color: var(--color-text-primary);
  background: var(--color-purple);
  border-radius: var(--radius-sm);
  clip-path: polygon(10px 0%, 100% 0%, calc(100% - 10px) 100%, 0% 100%);
  opacity: 1;
}
.ts-item.ts-cta-primary:hover,
.ts-item.ts-cta-primary.is-selected {
  color: var(--color-text-primary);
  background: var(--color-purple-bright);
}
.ts-item.ts-cta-primary:active { background: var(--color-purple-dim); }
.ts-item.ts-cta-primary.is-selected::before { content: none; }

/* Ghost CTA — 1px teal border ("LEADERBOARD") */
.ts-item.ts-cta-ghost {
  padding: 15px 36px;
  font-size: clamp(14px, 1.3vw, 18px);
  font-weight: 700;
  letter-spacing: var(--tracking-wide);
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
  border-radius: var(--radius-sm);
  opacity: 1;
}
.ts-item.ts-cta-ghost:hover,
.ts-item.ts-cta-ghost.is-selected {
  color: var(--color-accent);
  background: rgba(0, 229, 196, 0.08);
}
.ts-item.ts-cta-ghost:active { background: rgba(0, 229, 196, 0.15); }
.ts-item.ts-cta-ghost.is-selected::before { content: none; }

/* Tertiary — small muted OPTIONS link under the CTAs */
.ts-item.ts-tertiary {
  padding: 8px 22px;
  font-size: clamp(13px, 1.2vw, 16px);
  font-weight: 700;
  letter-spacing: var(--tracking-wider);
  color: var(--color-text-secondary);
  opacity: 1;
}
.ts-item.ts-tertiary:hover,
.ts-item.ts-tertiary.is-selected {
  color: var(--color-purple-bright);
}
.ts-item.ts-tertiary.is-selected::before { content: "▸"; left: 2px; }

/* Scanline footer — tiny transmission line flanked by rules */
.ts-scanline {
  position: absolute;
  bottom: 20px;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 24px;
  opacity: 0.6;
  pointer-events: none;
}
.ts-scanline::before,
.ts-scanline::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--color-border);
}
.ts-scanline-text {
  font-family: var(--font-display);
  font-size: clamp(11px, 1vw, 14px);
  letter-spacing: var(--tracking-wider);
  color: var(--color-purple-bright);
  white-space: nowrap;
}
#title-screen.is-story .ts-scanline { display: none; }

